import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-endowment-fund',
  templateUrl: './endowment-fund.page.html',
  styleUrls: ['./endowment-fund.page.scss'],
})
export class EndowmentFundPage implements OnInit {
  routeData: any;
  status: any;
  uidse: any;
  class = [
    {label: "UKG",value: 1 },
    {label: "I",value: 2 },
    {label: "II",value: 3 },
    {label: "III",value: 4 },
  ]
  onAgency: boolean;
  
  constructor(private route: ActivatedRoute,
    private router: Router) { }

  ngOnInit() {
  }
 
  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.status = this.routeData.queryParams.status;
    this.uidse = this.routeData.queryParams.uidse;
    parseInt(this.status); 
    console.log(this.status)

  }
  
  onOfChange(event,id){
    if(id == 2){
      this.onAgency = false;
    }
    if(id == 1 ){
      this.onAgency = true;
    }
  }

  onSave() {
   let data = parseInt(this.status)
    console.log(data)
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: data,"uidse": this.uidse }, skipLocationChange: false
    });
  }

  goToBack() {
     this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: this.status, "uidse": this.uidse }, skipLocationChange: false
    });
  }

}
